class OOBank {}

class Branch {
  + address : string
  + branchNumber : int
}

class Division {}

class Subdivision {}

class Employee {}

class Customer {
}

class Account {
  + accountNumber : int
  + balance : double
  + creditOrOverdraftLimit : double
  + interestRate : float
  + monthlyFee : float
}

class MortgageAccount extends Account {
  + propertyCollateral : string
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate : date
}

class SecondaryCard {}

class Privilege {}

class Manager {}

Employee "1" -- "*" Customer : personal banker
Division "1" -- "*" Subdivision
Division "1" -- "1" Manager
