Subdivision "1" -- "*" Branch
OOBank "1" -- "*" Division
OOBank "1" -- "*" Branch
Branch "1" -- "*" Account
Account "1" -- "*" Privilege
Account "1" -- "0..*" SecondaryCard
Account "1" -- "1..*" Customer : joint account

@enduml

